1	import 'dart:async';
2	
3	import 'package:cerne/core/network/failure.dart';
4	import 'package:cerne/features/capture/domain/entities/recognition_failure.dart';
5	import 'package:cerne/features/capture/domain/repositories/audio_capture_repository.dart';
6	import 'package:cerne/features/capture/domain/repositories/photo_capture_repository.dart';
7	import 'package:cerne/features/capture/domain/usecases/save_audio_entry_usecase.dart';
8	import 'package:cerne/features/capture/domain/usecases/save_photo_entry_usecase.dart';
9	import 'package:cerne/features/capture/domain/usecases/save_text_entry_usecase.dart';
10	import 'package:cerne/features/capture/presentation/bloc/insertion_modal_event.dart';
11	import 'package:cerne/features/capture/presentation/bloc/insertion_modal_state.dart';
12	import 'package:flutter_bloc/flutter_bloc.dart';
13	
14	const _offlineMessage = 'Sem conexão. Conecte-se à internet para salvar.';
15	const _noSpeechMessage = 'Não foi possível identificar fala no áudio.';
16	const _genericAudioMessage = 'Não foi possível processar o áudio.';
17	const _noTextMessage = 'Não foi possível identificar texto na imagem.';
18	
19	/// One screen-scoped bloc for the whole Insertion Modal
20	/// (contracts/insertion-modal-bloc.md) — created fresh by `BlocProvider`
21	/// every time `showModalBottomSheet` opens the modal, which is what makes
22	/// FR-002's "reset every tab... each time the modal is freshly opened" true
23	/// without an explicit reset event.
24	class InsertionModalBloc extends Bloc<InsertionModalEvent, InsertionModalState> {
25	  InsertionModalBloc({
26	    required this._saveTextEntryUseCase,
27	    required this._audioCaptureRepository,
28	    required this._saveAudioEntryUseCase,
29	    required this._photoCaptureRepository,
30	    required this._savePhotoEntryUseCase,
31	  }) : super(const InsertionModalTexto()) {
32	    on<TabSelected>(_onTabSelected);
33	    on<TextDraftChanged>(_onTextDraftChanged);
34	    on<SaveTextSubmitted>(_onSaveTextSubmitted);
35	    on<AudioTimerTicked>(_onAudioTimerTicked);
36	    on<AudioStopRequested>(_onAudioStopRequested);
37	    on<PhotoSourceSelected>(_onPhotoSourceSelected);
38	    on<RetryRequested>(_onRetryRequested);
39	    on<ModalClosed>(_onModalClosed);
40	  }
41	
42	  final SaveTextEntryUseCase _saveTextEntryUseCase;
43	  final AudioCaptureRepository _audioCaptureRepository;
44	  final SaveAudioEntryUseCase _saveAudioEntryUseCase;
45	  final PhotoCaptureRepository _photoCaptureRepository;
46	  final SavePhotoEntryUseCase _savePhotoEntryUseCase;
47	
48	  final _closeController = StreamController<void>.broadcast();
49	
50	  /// A one-shot side effect, not a state (FR-011, contracts/
51	  /// insertion-modal-bloc.md) — `InsertionModalPage` listens to this to pop
52	  /// the sheet. There is nothing to render for "success", so it never
53	  /// becomes a dedicated `InsertionModalState` case.
54	  Stream<void> get closeRequests => _closeController.stream;
55	
56	  String _textDraft = '';
57	  String? _pendingAudioPath;
58	  String? _pendingImagePath;
59	  Timer? _audioTicker;
60	
61	  Future<void> _onTabSelected(
62	    TabSelected event,
63	    Emitter<InsertionModalState> emit,
64	  ) async {
65	    if (state is InsertionModalAudioRecording) {
66	      // Switching away mid-recording discards it (Edge Cases) — nothing
67	      // from an abandoned capture may survive (FR-008).
68	      _audioCaptureRepository.discard();
69	      _stopAudioTicker();
70	      _pendingAudioPath = null;
71	    }
72	
73	    switch (event.tab) {
74	      case CaptureTab.texto:
75	        emit(InsertionModalTexto(text: _textDraft));
76	      case CaptureTab.audio:
77	        await _startAudioTab(emit);
78	      case CaptureTab.foto:
79	        emit(const InsertionModalFotoCaptura());
80	    }
81	  }
82	
83	  Future<void> _startAudioTab(Emitter<InsertionModalState> emit) async {
84	    final hasPermission = await _audioCaptureRepository.hasPermission();
85	    if (!hasPermission) {
86	      emit(const InsertionModalAudioPermissionDenied());
87	      return;
88	    }
89	    await _audioCaptureRepository.start();
90	    emit(const InsertionModalAudioRecording(elapsed: Duration.zero));
91	    _startAudioTicker();
92	  }
93	
94	  void _startAudioTicker() {
95	    _audioTicker?.cancel();
96	    _audioTicker = Timer.periodic(
97	      const Duration(seconds: 1),
98	      (_) => add(const AudioTimerTicked()),
99	    );
100	  }
101	
102	  void _stopAudioTicker() {
103	    _audioTicker?.cancel();
104	    _audioTicker = null;
105	  }
106	
107	  void _onTextDraftChanged(
108	    TextDraftChanged event,
109	    Emitter<InsertionModalState> emit,
110	  ) {
111	    _textDraft = event.text;
112	    emit(InsertionModalTexto(text: event.text));
113	  }
114	
115	  void _onAudioTimerTicked(
116	    AudioTimerTicked event,
117	    Emitter<InsertionModalState> emit,
118	  ) {
119	    final current = state;
120	    if (current is InsertionModalAudioRecording) {
121	      emit(
122	        InsertionModalAudioRecording(
123	          elapsed: current.elapsed + const Duration(seconds: 1),
124	        ),
125	      );
126	    }
127	  }
